  1392  /**
  1393   * gnutls_pkcs12_simple_parse:
  1394   * @p12: A pkcs12 type
  1395   * @password: optional password used to decrypt the structure, bags and keys.
  1396   * @key: a structure to store the parsed private key.
  1397   * @chain: the corresponding to key certificate chain (may be %NULL)
  1398   * @chain_len: will be updated with the number of additional (may be %NULL)
  1399   * @extra_certs: optional pointer to receive an array of additional
  1400   *             certificates found in the PKCS12 structure (may be %NULL).
  1401   * @extra_certs_len: will be updated with the number of additional
  1402   *                 certs (may be %NULL).
  1403   * @crl: an optional structure to store the parsed CRL (may be %NULL).
  1404   * @flags: should be zero or one of GNUTLS_PKCS12_SP_*
  1405   *
  1406   * This function parses a PKCS12 structure in @pkcs12 and extracts the
  1407   * private key, the corresponding certificate chain, any additional
  1408   * certificates and a CRL. The structures in @key, @chain @crl, and @extra_certs
  1409   * must not be initialized.
  1410   *
  1411   * The @extra_certs and @extra_certs_len parameters are optional
  1412   * and both may be set to %NULL. If either is non-%NULL, then both must
  1413   * be set. The value for @extra_certs is allocated
  1414   * using gnutls_malloc().
  1415   *
  1416   * Encrypted PKCS12 bags and PKCS8 private keys are supported, but
  1417   * only with password based security and the same password for all
  1418   * operations.
  1419   *
  1420   * Note that a PKCS12 structure may contain many keys and/or certificates,
  1421   * and there is no way to identify which key/certificate pair you want.
  1422   * For this reason this function is useful for PKCS12 files that contain
  1423   * only one key/certificate pair and/or one CRL.
  1424   *
  1425   * If the provided structure has encrypted fields but no password
  1426   * is provided then this function returns %GNUTLS_E_DECRYPTION_FAILED.
  1427   *
  1428   * Note that normally the chain constructed does not include self signed
  1429   * certificates, to comply with TLS' requirements. If, however, the flag
  1430   * %GNUTLS_PKCS12_SP_INCLUDE_SELF_SIGNED is specified then
  1431   * self signed certificates will be included in the chain.
  1432   *
  1433   * Prior to using this function the PKCS #12 structure integrity must
  1434   * be verified using gnutls_pkcs12_verify_mac().
  1435   *
  1436   * Returns: On success, %GNUTLS_E_SUCCESS (0) is returned, otherwise a
  1437   *   negative error value.
  1438   *
  1439   * Since: 3.1.0
  1440   **/
  1441  int
  1442  gnutls_pkcs12_simple_parse(gnutls_pkcs12_t p12,
  1443                             const char *password,
  1444                             gnutls_x509_privkey_t * key,
  1445                             gnutls_x509_crt_t ** chain,
  1446                             unsigned int *chain_len,
  1447                             gnutls_x509_crt_t ** extra_certs,
  1448                             unsigned int *extra_certs_len,
  1449                             gnutls_x509_crl_t * crl, unsigned int flags)
  1450  {
  1451          gnutls_pkcs12_bag_t bag = NULL;
  1452          gnutls_x509_crt_t *_extra_certs = NULL;
  1453          unsigned int _extra_certs_len = 0;
  1454          gnutls_x509_crt_t *_chain = NULL;
  1455          unsigned int _chain_len = 0;
  1456          int idx = 0;
  1457          int ret;
  1458          size_t cert_id_size = 0;
  1459          size_t key_id_size = 0;
  1460          uint8_t cert_id[20];
  1461          uint8_t key_id[20];
  1462          int privkey_ok = 0;
  1463          unsigned int i;
  1464          int elements_in_bag;
  1465
  1466          *key = NULL;
  1467
  1468          if (crl)
  1469                  *crl = NULL;
  1470
  1471          /* find the first private key */
  1472          for (;;) {
  1473
  1474                  ret = gnutls_pkcs12_bag_init(&bag);
  1475                  if (ret < 0) {
  1476                          bag = NULL;
  1477                          gnutls_assert();
  1478                          goto done;
  1479                  }
  1480
  1481                  ret = gnutls_pkcs12_get_bag(p12, idx, bag);
  1482                  if (ret == GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE) {
  1483                          gnutls_pkcs12_bag_deinit(bag);
  1484                          bag = NULL;
  1485                          break;
  1486                  }
  1487                  if (ret < 0) {
  1488                          gnutls_assert();
  1489                          goto done;
  1490                  }
  1491
  1492                  ret = gnutls_pkcs12_bag_get_type(bag, 0);
  1493                  if (ret < 0) {
  1494                          gnutls_assert();
  1495                          goto done;
  1496                  }
  1497
  1498                  if (ret == GNUTLS_BAG_ENCRYPTED) {
  1499                          if (password == NULL) {
  1500                                  ret =
  1501                                      gnutls_assert_val
  1502                                      (GNUTLS_E_DECRYPTION_FAILED);
  1503                                  goto done;
  1504                          }
  1505
  1506                          ret = gnutls_pkcs12_bag_decrypt(bag, password);
  1507                          if (ret < 0) {
  1508                                  gnutls_assert();
  1509                                  goto done;
  1510                          }
  1511                  }
  1512
  1513                  elements_in_bag = gnutls_pkcs12_bag_get_count(bag);
  1514                  if (elements_in_bag < 0) {
  1515                          gnutls_assert();
  1516                          goto done;
  1517                  }
  1518
  1519                  for (i = 0; i < (unsigned)elements_in_bag; i++) {
  1520                          int type;
  1521                          gnutls_datum_t data;
  1522
  1523                          type = gnutls_pkcs12_bag_get_type(bag, i);
  1524                          if (type < 0) {
  1525                                  gnutls_assert();
  1526                                  goto done;
  1527                          }
  1528
  1529                          ret = gnutls_pkcs12_bag_get_data(bag, i, &data);
  1530                          if (ret < 0) {
  1531                                  gnutls_assert();
  1532                                  goto done;
  1533                          }
  1534
  1535                          switch (type) {
  1536                          case GNUTLS_BAG_PKCS8_ENCRYPTED_KEY:
  1537                                  if (password == NULL) {
  1538                                          ret =
  1539                                              gnutls_assert_val
  1540                                              (GNUTLS_E_DECRYPTION_FAILED);
  1541                                          goto done;
  1542                                  }
  1543
  1544                                  /* fallthrough */
  1545                          case GNUTLS_BAG_PKCS8_KEY:
  1546                                  if (*key != NULL) {     /* too simple to continue */
  1547                                          gnutls_assert();
  1548                                          break;
  1549                                  }
  1550
  1551                                  ret = gnutls_x509_privkey_init(key);
  1552                                  if (ret < 0) {
  1553                                          gnutls_assert();
  1554                                          goto done;
  1555                                  }
  1556
  1557                                  ret = gnutls_x509_privkey_import_pkcs8
  1558                                      (*key, &data, GNUTLS_X509_FMT_DER,
  1559                                       password,
  1560                                       type ==
  1561                                       GNUTLS_BAG_PKCS8_KEY ?
  1562                                       GNUTLS_PKCS_PLAIN : 0);
  1563                                  if (ret < 0) {
  1564                                          gnutls_assert();
  1565                                          goto done;
  1566                                  }
  1567
  1568                                  key_id_size = sizeof(key_id);
  1569                                  ret =
  1570                                      gnutls_x509_privkey_get_key_id(*key, 0,
  1571                                                                     key_id,
  1572                                                                     &key_id_size);
  1573                                  if (ret < 0) {
  1574                                          gnutls_assert();
  1575                                          goto done;
  1576                                  }
  1577
  1578                                  privkey_ok = 1; /* break */
  1579                                  break;
  1580                          default:
  1581                                  break;
  1582                          }
  1583                  }
  1584
  1585                  idx++;
  1586                  gnutls_pkcs12_bag_deinit(bag);
  1587                  bag = NULL;
  1588
  1589                  if (privkey_ok != 0)    /* private key was found */
  1590                          break;
  1591          }
  1592
  1593          if (privkey_ok == 0) {  /* no private key */
  1594                  gnutls_assert();
  1595                  return GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE;
  1596          }
  1597
  1598          /* now find the corresponding certificate
  1599           */
  1600          idx = 0;
  1601          bag = NULL;
  1602          for (;;) {
  1603                  ret = gnutls_pkcs12_bag_init(&bag);
  1604                  if (ret < 0) {
  1605                          bag = NULL;
  1606                          gnutls_assert();
  1607                          goto done;
  1608                  }
  1609
  1610                  ret = gnutls_pkcs12_get_bag(p12, idx, bag);
  1611                  if (ret == GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE) {
  1612                          gnutls_pkcs12_bag_deinit(bag);
  1613                          bag = NULL;
  1614                          break;
  1615                  }
  1616                  if (ret < 0) {
  1617                          gnutls_assert();
  1618                          goto done;
  1619                  }
  1620
  1621                  ret = gnutls_pkcs12_bag_get_type(bag, 0);
  1622                  if (ret < 0) {
  1623                          gnutls_assert();
  1624                          goto done;
  1625                  }
  1626
  1627                  if (ret == GNUTLS_BAG_ENCRYPTED) {
  1628                          ret = gnutls_pkcs12_bag_decrypt(bag, password);
  1629                          if (ret < 0) {
  1630                                  gnutls_assert();
  1631                                  goto done;
  1632                          }
  1633                  }
  1634
  1635                  elements_in_bag = gnutls_pkcs12_bag_get_count(bag);
  1636                  if (elements_in_bag < 0) {
  1637                          gnutls_assert();
  1638                          goto done;
  1639                  }
  1640
  1641                  for (i = 0; i < (unsigned)elements_in_bag; i++) {
  1642                          int type;
  1643                          gnutls_datum_t data;
  1644                          gnutls_x509_crt_t this_cert;
  1645
  1646                          type = gnutls_pkcs12_bag_get_type(bag, i);
  1647                          if (type < 0) {
  1648                                  gnutls_assert();
  1649                                  goto done;
  1650                          }
  1651
  1652                          ret = gnutls_pkcs12_bag_get_data(bag, i, &data);
  1653                          if (ret < 0) {
  1654                                  gnutls_assert();
  1655                                  goto done;
  1656                          }
  1657
  1658                          switch (type) {
  1659                          case GNUTLS_BAG_CERTIFICATE:
  1660                                  ret = gnutls_x509_crt_init(&this_cert);
  1661                                  if (ret < 0) {
  1662                                          gnutls_assert();
  1663                                          goto done;
  1664                                  }
  1665
  1666                                  ret =
  1667                                      gnutls_x509_crt_import(this_cert,
  1668                                                             &data,
  1669                                                             GNUTLS_X509_FMT_DER);
  1670                                  if (ret < 0) {
  1671                                          gnutls_assert();
  1672                                          gnutls_x509_crt_deinit(this_cert);
  1673                                          goto done;
  1674                                  }
  1675
  1676                                  /* check if the key id match */
  1677                                  cert_id_size = sizeof(cert_id);
  1678                                  ret =
  1679                                      gnutls_x509_crt_get_key_id(this_cert,
  1680                                                                 0, cert_id,
  1681                                                                 &cert_id_size);
  1682                                  if (ret < 0) {
  1683                                          gnutls_assert();
  1684                                          gnutls_x509_crt_deinit(this_cert);
  1685                                          goto done;
  1686                                  }
  1687
  1688                                  if (memcmp(cert_id, key_id, cert_id_size) != 0) {       /* they don't match - skip the certificate */
  1689                                          _extra_certs =
  1690                                                  gnutls_realloc_fast
  1691                                                  (_extra_certs,
  1692                                                   sizeof(_extra_certs
  1693                                                          [0]) *
  1694                                                   ++_extra_certs_len);
  1695                                          if (!_extra_certs) {
  1696                                                  gnutls_assert();
  1697                                                  ret =
  1698                                                          GNUTLS_E_MEMORY_ERROR;
  1699                                                  goto done;
  1700                                          }
  1701                                          _extra_certs
  1702                                                  [_extra_certs_len -
  1703                                                   1] = this_cert;
  1704                                          this_cert = NULL;
  1705                                  } else {
  1706                                          if (chain && _chain_len == 0) {
  1707                                                  _chain =
  1708                                                      gnutls_malloc(sizeof
  1709                                                                    (_chain
  1710                                                                     [0]) *
  1711                                                                    (++_chain_len));
  1712                                                  if (!_chain) {
  1713                                                          gnutls_assert();
  1714                                                          ret =
  1715                                                              GNUTLS_E_MEMORY_ERROR;
  1716                                                          goto done;
  1717                                                  }
  1718                                                  _chain[_chain_len - 1] =
  1719                                                      this_cert;
  1720                                                  this_cert = NULL;
  1721                                          } else {
  1722                                                  gnutls_x509_crt_deinit
  1723                                                      (this_cert);
  1724                                          }
  1725                                  }
  1726                                  break;
  1727
  1728                          case GNUTLS_BAG_CRL:
  1729                                  if (crl == NULL || *crl != NULL) {
  1730                                          gnutls_assert();
  1731                                          break;
  1732                                  }
  1733
  1734                                  ret = gnutls_x509_crl_init(crl);
  1735                                  if (ret < 0) {
  1736                                          gnutls_assert();
  1737                                          goto done;
  1738                                  }
  1739
  1740                                  ret =
  1741                                      gnutls_x509_crl_import(*crl, &data,
  1742                                                             GNUTLS_X509_FMT_DER);
  1743                                  if (ret < 0) {
  1744                                          gnutls_assert();
  1745                                          gnutls_x509_crl_deinit(*crl);
  1746                                          goto done;
  1747                                  }
  1748                                  break;
  1749
  1750                          case GNUTLS_BAG_ENCRYPTED:
  1751                                  /* XXX Bother to recurse one level down?  Unlikely to
  1752                                     use the same password anyway. */
  1753                          case GNUTLS_BAG_EMPTY:
  1754                          default:
  1755                                  break;
  1756                          }
  1757                  }
  1758
  1759                  idx++;
  1760                  gnutls_pkcs12_bag_deinit(bag);
  1761                  bag = NULL;
  1762          }
  1763
  1764          if (chain != NULL) {
  1765                  if (_chain_len != 1) {
  1766                          ret = GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE;
  1767                          goto done;
  1768                  }
  1769
  1770                  ret =
  1771                      make_chain(&_chain, &_chain_len, &_extra_certs,
  1772                                 &_extra_certs_len, flags);
  1773                  if (ret < 0) {
  1774                          gnutls_assert();
  1775                          goto done;
  1776                  }
  1777          }
  1778
  1779          ret = 0;
  1780
  1781        done:
  1782          if (bag)
  1783                  gnutls_pkcs12_bag_deinit(bag);
  1784
  1785          if (ret < 0) {
  1786                  if (*key) {
  1787                          gnutls_x509_privkey_deinit(*key);
  1788                          *key = NULL;
  1789                  }
  1790                  if (crl != NULL && *crl != NULL) {
  1791                          gnutls_x509_crl_deinit(*crl);
  1792                          *crl = NULL;
  1793                  }
  1794                  if (_extra_certs_len && _extra_certs != NULL) {
  1795                          for (i = 0; i < _extra_certs_len; i++)
  1796                                  gnutls_x509_crt_deinit(_extra_certs[i]);
  1797                          gnutls_free(_extra_certs);
  1798                  }
  1799                  if (_chain_len && _chain != NULL) {
  1800                          for (i = 0; i < _chain_len; i++)
  1801                                  gnutls_x509_crt_deinit(_chain[i]);
  1802                          gnutls_free(_chain);
  1803                  }
  1804
  1805                  return ret;
  1806          }
  1807
  1808          if (extra_certs && _extra_certs_len > 0) {
  1809                  *extra_certs = _extra_certs;
  1810                  *extra_certs_len = _extra_certs_len;
  1811          } else {
  1812                  if (extra_certs) {
  1813                          *extra_certs = NULL;
  1814                          *extra_certs_len = 0;
  1815                  }
