   652  /**
   653   * gnutls_pkcs12_bag_decrypt:
   654   * @bag: The bag
   655   * @pass: The password used for encryption, must be ASCII.
   656   *
   657   * This function will decrypt the given encrypted bag and return 0 on
   658   * success.
   659   *
   660   * Returns: On success, %GNUTLS_E_SUCCESS (0) is returned,
   661   *   otherwise a negative error code is returned.
   662   **/
   663  int gnutls_pkcs12_bag_decrypt(gnutls_pkcs12_bag_t bag, const char *pass)
   664  {
   665          int ret;
   666          gnutls_datum_t dec;
   667
   668          if (bag == NULL) {
   669                  gnutls_assert();
   670                  return GNUTLS_E_INVALID_REQUEST;
   671          }
   672
   673          if (bag->element[0].type != GNUTLS_BAG_ENCRYPTED) {
   674                  gnutls_assert();
   675                  return GNUTLS_E_INVALID_REQUEST;
   676          }
   677
   678          ret =
   679              _gnutls_pkcs7_decrypt_data(&bag->element[0].data, pass, &dec);
   680
   681          if (ret < 0) {
   682                  gnutls_assert();
   683                  return ret;
   684          }
   685
   686          /* decryption succeeded. Now decode the SafeContents
   687           * stuff, and parse it.
   688           */
   689
   690          _gnutls_free_datum(&bag->element[0].data);
   691
   692          ret = _pkcs12_decode_safe_contents(&dec, bag);
   693
   694          _gnutls_free_datum(&dec);
   695
   696          if (ret < 0) {
   697                  gnutls_assert();
   698                  return ret;
   699          }
   700
   701          return 0;
   702  }
